      "source": "parcels",
      "geometry": "polygon",
      "match": {
        "property": "properties.parcelState",
        "values": [
          "wa-parcel-state:created"
        ]
      },
      "kind": "parcel-created",
      "group": "parcel",
      "kindLabel": "Created",
      "initiallyVisible": true,
      "elevation": "flatten",
      "style": {
        "color": "#0a6ff6",
        "opacity": 0.5,
        "lineColor": "#06102b"
